package crypto

import (
	"bytes"
	"encoding/hex"
	"errors"
	"testing"
)

// Golden fixtures were generated by running control-plane's real pkg/crypto (origin/main)
// with a keyring of fixed key material. They pin byte-for-byte compatibility
// with the CPK1 blobs control-plane already wrote: a blob sealed by either
// implementation must open with the other.
//
// Key material: v1 = bytes 0x00..0x1f, v2 = bytes 0xa0..0xbf.
const (
	goldenKeyring   = "v2:oKGio6SlpqeoqaqrrK2ur7CxsrO0tba3uLm6u7y9vr8=,v1:AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="
	goldenPlaintext = "sk-golden-plaintext"
	goldenAAD       = "scope|org1|KEY"

	// control-plane sealed under primary v2. The 12 bytes after the 7-byte
	// header are the nonce it drew at random; they are replayed below.
	cpV2NoAAD = "43504b310276321041b85a8ada6dab4675b509501fdee674f54dd30728b95f4d4c9eeca15e7ca50f4b02ca5c9f8c3f547a6d69b04120"
	cpV2AAD   = "43504b31027632aa85d0df9b3d30b38ba8f28b0c7ff405277c578c961ff8a680e47c0f30ad12df2e58087bd6a986eb448311f2311e49"
	// control-plane sealed under a single-key keyring holding only v1.
	cpV1NoAAD = "43504b31027631d790d4e9b0e8200c4d7bbf41e89436580caaadd7f5cd8745afa24a6ade7d5b5f45845bdd09172f403f495389e5f6d8"
)

func fixedNonce(nonce []byte) func([]byte) error {
	return func(dst []byte) error { copy(dst, nonce); return nil }
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestGoldenControlPlaneBlobsOpenHere(t *testing.T) {
	kr, err := ParseKeyring(goldenKeyring)
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name, blob string
		aad        []byte
	}{
		{"v2 no aad", cpV2NoAAD, nil},
		{"v2 aad", cpV2AAD, []byte(goldenAAD)},
		{"v1 (non-primary here) no aad", cpV1NoAAD, nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := kr.Open(mustHex(t, tc.blob), tc.aad)
			if err != nil || string(got) != goldenPlaintext {
				t.Fatalf("Open = %q, %v", got, err)
			}
		})
	}
	// The aad-bound blob must still refuse an unbound open.
	if _, err := kr.Open(mustHex(t, cpV2AAD), nil); err == nil {
		t.Fatal("aad-bound control-plane blob opened without aad")
	}
}

// Replaying control-plane's nonce through this implementation must reproduce
// control-plane's blob exactly: that is the "and vice versa" direction, since
// control-plane's Decrypt is the same AEAD over the same header ‖ aad.
func TestGoldenBlobsAreReproducedByteForByte(t *testing.T) {
	cases := []struct {
		name, blob, keyring string
		aad                 []byte
	}{
		{"v2 no aad", cpV2NoAAD, goldenKeyring, nil},
		{"v2 aad", cpV2AAD, goldenKeyring, []byte(goldenAAD)},
		{"v1 single-key keyring", cpV1NoAAD, "v1:AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=", nil},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			want := mustHex(t, tc.blob)
			kr, err := ParseKeyring(tc.keyring)
			if err != nil {
				t.Fatal(err)
			}
			kr.readNonce = fixedNonce(want[7 : 7+12])
			got, err := kr.Seal([]byte(goldenPlaintext), tc.aad)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(got, want) {
				t.Fatalf("sealed bytes differ from control-plane\n got %x\nwant %x", got, want)
			}
		})
	}
}

func TestGoldenV1PrefixBytes(t *testing.T) {
	if !bytes.HasPrefix(mustHex(t, cpV1NoAAD), mustPrefix(t, "v1")) {
		t.Fatal("control-plane's v1 blob does not start with EnvelopePrefixForKeyID(v1)")
	}
	if !bytes.Equal(mustPrefix(t, "v1"), []byte{'C', 'P', 'K', '1', 0x02, 'v', '1'}) {
		t.Fatal("v1 prefix bytes changed")
	}
}

func TestGoldenLegacyBlobIsUnversioned(t *testing.T) {
	kr, _ := ParseKeyring(goldenKeyring)
	// Pre-keyring format: raw nonce ‖ ciphertext, no header.
	legacy := mustHex(t, cpV1NoAAD)[7:]
	if _, err := kr.Open(legacy, nil); !errors.Is(err, ErrUnversionedCiphertext) {
		t.Fatalf("want ErrUnversionedCiphertext, got %v", err)
	}
}
